<template>
    <div>
        <Head title="Grid System" />

        <Card class="card-plain">
            <section v-for="example in examples" :key="example.title">
                <h4 class="card-title ps-3">
                    {{ example.title }}
                    <small>{{ example.description }}</small>
                </h4>
                <div v-for="(row, rowIndex) in example.rows" :key="rowIndex" class="row">
                    <div v-for="(column, columnIndex) in row" :key="columnIndex" :class="column">
                        <Card>
                            <div class="text-center">
                                <code>{{ column }}</code>
                            </div>
                        </Card>
                    </div>
                </div>
            </section>
        </Card>

        <h3 class="title mt-4 text-center">Paragraphs</h3>
        <Card>
            <div v-for="(row, rowIndex) in paragraphRows" :key="rowIndex" class="row">
                <div v-for="(column, columnIndex) in row" :key="columnIndex" :class="column">
                    <h3>{{ columnIndex === 0 ? 'Some Title Here' : 'Another Title Here' }}</h3>
                    <p>{{ paragraph }}</p>
                </div>
            </div>
        </Card>
    </div>
</template>

<script>
import { Head } from '@inertiajs/vue3';
import Card from '@scaffold/components/Card.vue';

export default {
    name: 'GridDemo',
    components: { Card, Head },
    layout: { pageTitle: 'Grid System' },
    data() {
        return {
            examples: [
                { title: 'XS Grid', description: 'Always horizontal', rows: [Array(3).fill('col-4')] },
                { title: 'SM Grid', description: 'Horizontal from 576px', rows: [Array(3).fill('sm:col-4')] },
                { title: 'MD Grid', description: 'Horizontal from 768px', rows: [Array(3).fill('md:col-4')] },
                { title: 'LG Grid', description: 'Horizontal from 992px', rows: [Array(3).fill('lg:col-4')] },
                { title: 'XL Grid', description: 'Horizontal from 1200px', rows: [Array(3).fill('xl:col-4')] },
                { title: 'Mixed Grid', description: 'Different widths at different breakpoints', rows: [Array(4).fill('sm:col-6 lg:col-3')] },
                {
                    title: 'Offset Grid',
                    description: 'Add space using auto margins',
                    rows: [
                        ['md:col-3', 'md:col-3 ms-auto'],
                        ['md:col-4 mx-auto', 'md:col-4 mx-auto'],
                        ['md:col-6 mx-auto'],
                    ],
                },
            ],
            paragraphRows: [
                ['sm:col-6', 'sm:col-6'],
                ['sm:col-4', 'sm:col-4', 'sm:col-4'],
                ['sm:col-4', 'sm:col-8'],
            ],
            paragraph: 'One morning, when Gregor Samsa woke from troubled dreams, he found himself transformed in his bed into a horrible vermin. He lay on his armour-like back, and if he lifted his head a little he could see his brown belly, slightly domed and divided by arches into stiff sections. The bedding was hardly able to cover it and seemed ready to slide off any moment.',
        };
    },
};
</script>
